leds->enable_all();
bool on = true;
while (true)
{
  if (on)
  {
    leds->led_off(0);
    leds->led_on(1);
  }
  else
  {
     leds->led_on(0);
     leds->led_off(1);
  }
  on = !on;
  Timeout t{100};
  thread_sleep(&t);
